__all__ = ['table_from_frame', 'table_to_frame']


def table_to_frame(tab, include_metas=False):
    """
    Convert Orange.data.Table to pandas.DataFrame

    Parameters
    ----------
    tab : Orange.data.Table
    include_metas : boolean
        If True, include metas in the resulting dataframe.

    Returns
    -------
    pandas.DataFrame
    """

    def _to_series(var, values):
        if var.is_discrete:
            codes = np.where(np.isnan(values), -1, values.astype(int))
            return pd.Series(pd.Categorical.from_codes(
                codes, categories=var.values, ordered=True))
        elif var.is_time:
            s = pd.Series(values)
            s = s.map(lambda v: var.repr_val(v) if not np.isnan(v) else np.nan)
            return pd.to_datetime(s, infer_datetime_format=True)
        elif var.is_string:
            return pd.Series(values.astype(object))
        else:
            return pd.Series(values)

    vars_ = list(tab.domain.attributes) + list(tab.domain.class_vars)
    data = [tab.X, tab.Y.reshape(len(tab), len(tab.domain.class_vars))]
    if include_metas:
        vars_ += list(tab.domain.metas)
        data.append(tab.metas)

    columns = {}
    for var, block in zip(_iter_columns(vars_, data)):
        columns[var.name] = _to_series(var, block)

    return pd.DataFrame(columns)


def _iter_columns(vars_, data):
    i = 0
    for arr in data:
        for j in range(arr.shape[1]):
            yield vars_[i], arr[:, j]
            i += 1

